// ch5/modparams/modparams1/modparams1.c
[ ... ]
/* Module parameters */
static int mp_debug_level;
module_param(mp_debug_level, int, 0660);
MODULE_PARM_DESC(mp_debug_level,
"Debug level [0-2]; 0 => no debug messages, 2 => high verbosity");
static char *mp_strparam = "My string param";
module_param(mp_strparam, charp, 0660);
MODULE_PARM_DESC(mp_strparam, "A demo string parameter");
Here, the mp prefix stands for module parameter. It’s not required to name it that way, of
course; it is pedantic, but consistently following such conventions helps by making the
reading of large codebases a bit more intuitive.
An aside: in the static int mp_debug_level; statement above, there is no harm in
changing it to static int mp_debug_level = 0;, thus explicitly initializing the variable
to 0, right? Well, no: the kernel’s scripts/checkpatch.pl script output reveals that this
is not considered a good coding style by the kernel community; if you do so, it triggers
this “error”:
ERROR: do not initialise statics to 0
#28: FILE: modparams1.c:28:
+static int mp_debug_level = 0;

