// ch5/fp_in_kernel/fp_in_kernel.c
static double num = 22.0, den = 7.0, mypi;
static int __init fp_in_lkm_init (void)
{
[...]
kernel_fpu_begin();
mypi = num/den;
kernel_fpu_end();
# if 1
pr_info("%s: PI = %.4f = %.4f\n", OURMODNAME, mypi, num/den);
# endif
return 0; /* success */
}
The recommendation is clear: the typical module (or driver) developer should perform
only integer arithmetic within the kernel.

